import logging
import os
from functools import wraps

from math_verify.errors import TimeoutException

logger = logging.getLogger(__name__)


def timeout(timeout_seconds: int | None = 10):
    if timeout_seconds is None or timeout_seconds <= 0:
        def no_timeout_decorator(func):
            return func

        return no_timeout_decorator

    if os.name == "posix":
        import signal

        def decorator(func):
            def handler(signum, frame):
                raise TimeoutException("Operation timed out!")

            @wraps(func)
            def wrapper(*args, **kwargs):
                old_handler = signal.getsignal(signal.SIGALRM)
                signal.signal(signal.SIGALRM, handler)
                signal.alarm(timeout_seconds)
                try:
                    return func(*args, **kwargs)
                finally:
                    signal.alarm(0)
                    signal.signal(signal.SIGALRM, old_handler)

            return wrapper

        return decorator

    from multiprocessing import Process, Queue

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            queue = Queue()

            def run_func(q, a, kw):
                try:
                    q.put((True, func(*a, **kw)))
                except Exception as exc:  # pragma: no cover - windows fallback
                    q.put((False, exc))

            process = Process(target=run_func, args=(queue, args, kwargs))
            process.start()
            process.join(timeout_seconds)
            if process.is_alive():  # pragma: no cover - windows fallback
                process.terminate()
                process.join()
                raise TimeoutException("Operation timed out!")

            success, value = queue.get()
            if success:
                return value
            raise value

        return wrapper

    return decorator

