from __future__ import annotations

from textwrap import dedent
from typing import Any, Callable, Optional

from math_verify.few_shots import GSM8K_FEW_SHOTS, MATH_HARD_FEW_SHOTS
from math_verify.metric import math_metric
from math_verify.parser import ExprExtractionConfig, LatexExtractionConfig

try:  # pragma: no cover - optional dependency
    import numpy as np
    from lighteval.metrics.dynamic_metrics import SampleLevelMetric
    from lighteval.metrics.utils.metric_utils import MetricCategory, MetricUseCase
    from lighteval.tasks.lighteval_task import LightevalTaskConfig
    from lighteval.tasks.requests import Doc
except Exception:  # pragma: no cover - optional dependency
    np = None
    SampleLevelMetric = MetricCategory = MetricUseCase = LightevalTaskConfig = Doc = None


def _require_lighteval():
    if Doc is None:  # pragma: no cover - optional dependency
        raise ImportError(
            "math_verify.tasks requires the optional 'lighteval' dependency group."
        )


def as_lighteval_metric(
    metric: Callable[[list[str], list[str]], tuple[float, Optional[tuple[list[str], list[str]]]]]
):
    _require_lighteval()

    def sample_level_fn(formatted_doc: Any, golds: list[str], predictions: list[str]) -> float:
        result, extracted_predictions = metric(golds, predictions)
        if extracted_predictions is not None:
            if not getattr(formatted_doc, "specific", None):
                formatted_doc.specific = {}
            formatted_doc.specific["extracted_predictions"] = extracted_predictions
        return result

    return SampleLevelMetric(
        metric_name="extractive_match",
        sample_level_fn=sample_level_fn,
        category=MetricCategory.GENERATIVE,
        use_case=MetricUseCase.ACCURACY,
        corpus_level_fn=np.mean,
        higher_is_better=True,
    )


def _build_doc(question: str, answer: str):
    _require_lighteval()
    return Doc(
        query=dedent(
            f"""\
            Question: {question}
            Step-by-Step Answer:\
            """
        ).strip(),
        choices=[answer],
        gold_index=0,
    )


def math_hard_prompt_function(x: dict, task_name: str):
    shot = (
        MATH_HARD_FEW_SHOTS[min(x["__index"], len(MATH_HARD_FEW_SHOTS) - 1)]
        if x.get("__few_shots")
        else None
    )
    return _build_doc(
        shot["question"] if shot else x["problem"],
        shot["answer"] if shot else str(x["solution"]),
    )


def math_prompt_function(x: dict, task_name: str):
    shot = (
        MATH_HARD_FEW_SHOTS[min(x["__index"], len(MATH_HARD_FEW_SHOTS) - 1)]
        if x.get("__few_shots")
        else None
    )
    return _build_doc(
        shot["question"] if shot else x["problem"],
        shot["answer"] if shot else str(x["answer"]),
    )


