import logging
import re
from itertools import product

from latex2sympy2_extended import is_expr_of_only_symbols
from latex2sympy2_extended.logic import And
from latex2sympy2_extended.sets import FiniteSet
from sympy import (
    Basic,
    E,
    Eq,
    Float,
    GreaterThan,
    Integer,
    Interval,
    LessThan,
    MatrixBase,
    MatrixExpr,
    Mul,
    Number,
    Rational,
    Set,
    StrictGreaterThan,
    StrictLessThan,
    Symbol,
    Tuple,
    UnevaluatedExpr,
    default_sort_key,
    nan,
    ordered,
    simplify,
    solve,
    zoo,
)
from sympy import FiniteSet as SympyFiniteSet
from sympy.core.function import UndefinedFunction
from sympy.core.relational import Relational

from math_verify.errors import TimeoutException
from math_verify.utils import timeout

logger = logging.getLogger(__name__)

TIMEOUT_WARNING_SHOWN = False

INVERSE_RELATIONS = {
    GreaterThan: LessThan,
    LessThan: GreaterThan,
    StrictGreaterThan: StrictLessThan,
    StrictLessThan: StrictGreaterThan,
    Eq: Eq,
}


def safe_sympy_doit(expr: Basic | MatrixBase):
    try:
        return expr.doit()
    except Exception:
        return expr


def get_pct_val(expr, default=None):
    if (
        isinstance(expr, Mul)
        and len(expr.args) == 2
        and expr.args[1] == UnevaluatedExpr(Rational(1, 100))
    ):
        return expr.args[0]
    return default


def is_atomic_or_pct_atomic(expr: Basic | MatrixBase, atomic_type: type) -> bool:
    return isinstance(expr, atomic_type) or (
        isinstance(expr, Mul)
        and len(expr.args) == 2
        and expr.args[1] == UnevaluatedExpr(Rational(1, 100))
        and isinstance(expr.args[0], atomic_type)
    )


def sympy_numeric_eq(
    gold: Basic | MatrixBase,
    target: Basic | MatrixBase,
    float_rounding: int,
    numeric_precision: int,
) -> bool:
    if isinstance(gold, (MatrixBase, MatrixExpr)) and isinstance(
        target, (MatrixBase, MatrixExpr)
    ):
        gold = safe_sympy_doit(gold)
        target = safe_sympy_doit(target)
        if isinstance(gold, MatrixBase) and isinstance(target, MatrixBase):
            if gold.shape == target.shape:
                return all(
                    sympy_numeric_eq(g, t, float_rounding, numeric_precision)
                    for g, t in zip(gold.flat(), target.flat(), strict=True)
                )
            return False

    elif is_atomic_or_pct_atomic(gold, Number) or is_atomic_or_pct_atomic(
        target, Number
    ):
        if is_atomic_or_pct_atomic(gold, Float) or is_atomic_or_pct_atomic(
            target, Float
        ):
            gold = safe_sympy_doit(gold)
            target = safe_sympy_doit(target)
            try:
                return gold.round(float_rounding) == target.round(float_rounding)
            except Exception:
                return False
        if is_atomic_or_pct_atomic(gold, Integer) and is_atomic_or_pct_atomic(
            target, Integer
        ):
            return get_pct_val(gold, gold) == get_pct_val(target, target)
        return safe_sympy_doit(gold) == safe_sympy_doit(target)

    try:
        return (gold - target).evalf(chop=True, n=numeric_precision) == 0  # type: ignore[operator]
    except Exception:
        return False


def sympy_symbolic_eq(gold: Basic | MatrixBase, target: Basic | MatrixBase) -> bool:
    try:
        diff = simplify(gold - target)  # type: ignore[operator]
    except Exception:
        return False
    if isinstance(diff, MatrixBase):
        return bool(diff.is_zero_matrix)
    if isinstance(diff, Basic):
        return bool(diff.is_zero)
    return False


def unwrap_eq(expr):
    if is_assignment_relation(expr):
        return take_last_relation(expr).rhs
    return expr


def sort_key(expr):
    try:
        return default_sort_key(unwrap_eq(expr).evalf())
    except Exception:
        return default_sort_key(unwrap_eq(expr))


def sympy_deep_compare_set_and_tuple(
    gold: SympyFiniteSet | Tuple,
    target: SympyFiniteSet | Tuple,
    float_rounding: int,
    numeric_precision: int,
) -> bool:
    if len(gold) != len(target):
        return False

    if isinstance(gold, SympyFiniteSet):
        gold_args = list(ordered(gold.args, keys=sort_key, default=False))
        target_args = list(ordered(target.args, keys=sort_key, default=False))
    elif isinstance(gold, Tuple) and isinstance(target, FiniteSet):
        gold_args = gold.args
        target_args = target._unsorted_args
    elif isinstance(target, SympyFiniteSet):
        gold_args = gold.args
        target_args = list(ordered(target.args, keys=sort_key, default=False))
    else:
        gold_args = gold.args
        target_args = target.args

    return all(
        sympy_expr_eq(g, t, float_rounding, numeric_precision)
        for g, t in zip(gold_args, target_args, strict=True)
    )


def sympy_compare_interval(
    gold: Interval,
    target: Interval,
    float_rounding: int,
    numeric_precision: int,
) -> bool:
    return (
        gold.left_open == target.left_open
        and gold.right_open == target.right_open
        and sympy_expr_eq(gold.start, target.start, float_rounding, numeric_precision)
        and sympy_expr_eq(gold.end, target.end, float_rounding, numeric_precision)
    )


def sympy_solve_and_compare(
    gold: Relational,
    target: Relational,
    float_rounding: int,
    numeric_precision: int,
) -> bool:
    solved_gold = list(ordered(solve(gold, gold.free_symbols)))
    solved_target = list(ordered(solve(target, target.free_symbols)))
    if isinstance(gold, Eq) and isinstance(target, Eq):
        return all(
            all(
                g_k == t_k
                and sympy_expr_eq(g_v, t_v, float_rounding, numeric_precision)
                for (g_k, g_v), (t_k, t_v) in zip(
                    sorted(g.items()), sorted(t.items()), strict=True
                )
            )
            for g, t in zip(
                ordered(solved_gold, keys=sort_key, default=False),
                ordered(solved_target, keys=sort_key, default=False),
                strict=True,
            )
        )
    return sympy_expr_eq(solved_gold, solved_target, float_rounding, numeric_precision)


def sympy_compare_relational(
    gold: Relational | And,
    target: Relational | And,
    float_rounding: int,
    numeric_precision: int,
) -> bool:
    if isinstance(gold, And) and isinstance(target, And):
        return all(
            sympy_compare_relational(g, t, float_rounding, numeric_precision)
            for g, t in zip(gold._unsorted_args, target._unsorted_args, strict=True)
        )
    if not isinstance(gold, Relational) or not isinstance(target, Relational):
        return False

    def flipped_equal(a: Relational, b: Relational) -> bool:
        try:
            return sympy_expr_eq(
                a.lhs - a.rhs,
                b.rhs - b.lhs,
                float_rounding,
                numeric_precision,
            )  # type: ignore[operator]
        except Exception:
            return False

    try:
        if type(gold) is type(target) and sympy_expr_eq(
            gold.lhs - gold.rhs,
            target.lhs - target.rhs,
            float_rounding,
            numeric_precision,
        ):  # type: ignore[operator]
            return True
    except Exception:
        pass

    if INVERSE_RELATIONS[type(gold)] is type(target) and flipped_equal(gold, target):  # type: ignore[index]
        return True

    try:
        return sympy_solve_and_compare(gold, target, float_rounding, numeric_precision)
    except Exception:
        return False


def sympy_str_eq(gold: Basic | MatrixBase, target: Basic | MatrixBase) -> bool:
    if gold == nan or gold == zoo:
        raise ValueError("Can't evaluate nan or zoo")
    try:
        return gold == target
    except Exception:
        return False


def sympy_compare_sets(
    gold: Set | Basic | MatrixBase | Tuple,
    target: Set | Basic | MatrixBase | Tuple,
    float_rounding: int,
    numeric_precision: int,
) -> bool:
    gold_set = gold if isinstance(gold, (Set, Tuple)) else SympyFiniteSet(gold)
    target_set = target if isinstance(target, (Set, Tuple)) else SympyFiniteSet(target)

    if isinstance(gold_set, Interval) and isinstance(target_set, Interval):
        return sympy_compare_interval(
            gold_set, target_set, float_rounding, numeric_precision
        )
    if gold_set == target_set:
        return True

    try:
        if (
            isinstance(gold_set, Set)
            and isinstance(target_set, Set)
            and gold_set.symmetric_difference(target_set).is_empty
        ):
            return True
    except Exception:
        pass

    if isinstance(gold_set, (SympyFiniteSet, Tuple)) and isinstance(
        target_set, (SympyFiniteSet, Tuple)
    ):
        return sympy_deep_compare_set_and_tuple(
            gold_set, target_set, float_rounding, numeric_precision
        )

    if isinstance(gold_set, Interval) and isinstance(target_set, (SympyFiniteSet, Tuple)):
        if gold_set.is_open and len(target_set) == 2:
            return sympy_deep_compare_set_and_tuple(
                Tuple(gold_set.start, gold_set.end),
                target_set,
                float_rounding,
                numeric_precision,
            )

    if isinstance(target_set, Interval) and isinstance(gold_set, (SympyFiniteSet, Tuple)):
        if target_set.is_open and len(gold_set) == 2:
            return sympy_deep_compare_set_and_tuple(
                gold_set,
                Tuple(target_set.start, target_set.end),
                float_rounding,
                numeric_precision,
            )

    return False


def sympy_compare_symbols(gold: Basic | MatrixBase, target: Basic | MatrixBase) -> bool:
    if (isinstance(gold, Symbol) and gold.name.lower() == "e" and target == E) or (
        isinstance(target, Symbol) and target.name.lower() == "e" and gold == E
    ):
        return True

    if (
        isinstance(gold, Symbol)
        and isinstance(target, Mul)
        and all(arg == E or isinstance(arg, Symbol) for arg in target.args)
    ):
        return gold.name.lower() == "".join(
            arg.name if isinstance(arg, Symbol) else "e" for arg in target.args
        ).lower()

    if (
        isinstance(target, Symbol)
        and isinstance(gold, Mul)
        and all(arg == E or isinstance(arg, Symbol) for arg in gold.args)
    ):
        return target.name.lower() == "".join(
            arg.name if isinstance(arg, Symbol) else "e" for arg in gold.args
        ).lower()

    if isinstance(gold, Symbol) and isinstance(target, Symbol):
        gold_name = gold.name.lower() if len(gold.name) > 1 else gold.name
        target_name = target.name.lower() if len(target.name) > 1 else target.name
        return gold_name == target_name

    return str(gold) == str(target)


def is_relation(expr: Basic | MatrixBase) -> bool:
    if isinstance(expr, Relational):
        return True
    return isinstance(expr, And) and len(expr._unsorted_args) > 0 and all(
        isinstance(arg, Relational) for arg in expr._unsorted_args
    )


def is_equation(expr: Basic | MatrixBase) -> bool:
    if isinstance(expr, Eq):
        return True
    return isinstance(expr, And) and len(expr._unsorted_args) > 0 and all(
        isinstance(arg, Eq) for arg in expr._unsorted_args
    )


def is_assignment_relation(expr: Basic | MatrixBase) -> bool:
    if isinstance(expr, Eq) and is_expr_of_only_symbols(expr.lhs):
        return True
    return isinstance(expr, And) and len(expr._unsorted_args) > 0 and all(
        isinstance(arg, Eq) for arg in expr._unsorted_args
    ) and is_expr_of_only_symbols(expr._unsorted_args[0].lhs)


def take_last_relation(expr: And | Relational) -> Relational:
    if isinstance(expr, And):
        return take_last_relation(expr._unsorted_args[-1])
    return expr


def take_first_relation(expr: And | Relational) -> Relational:
    if isinstance(expr, And):
        return expr._unsorted_args[0]
    return expr


def unwrap_fcs(expr: Basic | MatrixBase) -> Basic | MatrixBase:
    if not isinstance(expr, Basic):
        return expr
    if hasattr(expr, "func") and isinstance(expr.func, UndefinedFunction):
        name = expr.func.__name__
        return Symbol(f"{name}_{'_'.join(str(unwrap_fcs(arg)) for arg in expr.args)}")
    try:
        args = [unwrap_fcs(arg) for arg in expr.args]
        if args:
            return expr.func(*args)
    except Exception:
        pass
    return expr


def sympy_expr_eq(
    gold: Basic | MatrixBase,
    target: Basic | MatrixBase,
    float_rounding: int,
    numeric_precision: int,
    allow_set_relation_comp: bool = False,
    strict: bool = True,
) -> bool:
    if not strict:
        try:
            gold_vars = gold.free_symbols
            target_vars = target.free_symbols
            if len(gold_vars) == len(target_vars):
                target = target.subs(list(zip(target_vars, gold_vars, strict=True)))
        except Exception:
            pass

    is_gold_assignment = is_assignment_relation(gold)
    is_target_assignment = is_assignment_relation(target)
    is_gold_equation = is_equation(gold)
    is_target_equation = is_equation(target)

    if is_gold_assignment:
        gold = Eq(take_first_relation(gold).lhs, take_last_relation(gold).rhs, evaluate=False)
    if is_target_assignment:
        target = Eq(
            take_first_relation(target).lhs,
            take_last_relation(target).rhs,
            evaluate=False,
        )

    if is_target_equation and not is_gold_equation:
        target = take_last_relation(target).rhs
    elif is_gold_assignment and not is_target_equation:
        gold = take_last_relation(gold).rhs

    if is_relation(gold) and isinstance(target, Set):
        try:
            gold = unwrap_fcs(gold).as_set()
        except Exception:
            pass

    if allow_set_relation_comp and is_relation(target) and isinstance(gold, Set):
        try:
            target = unwrap_fcs(target).as_set()
        except Exception:
            pass

    if sympy_str_eq(gold, target):
        return True
    if is_relation(gold) and is_relation(target):
        return sympy_compare_relational(gold, target, float_rounding, numeric_precision)
    if isinstance(gold, (Set, Tuple)) or isinstance(target, (Set, Tuple)):
        return sympy_compare_sets(gold, target, float_rounding, numeric_precision)
    if isinstance(gold, Symbol) or isinstance(target, Symbol):
        return sympy_compare_symbols(gold, target)
    if isinstance(gold, (Basic, MatrixBase)) and isinstance(target, (Basic, MatrixBase)):
        if sympy_numeric_eq(gold, target, float_rounding, numeric_precision):
            return True
        if sympy_symbolic_eq(gold, target):
            return True
    return False


complex_number_pattern = re.compile(
    r"""
    \\mathbb\{C\}|
    \\i\b|
    \bi\b|
    \\text\{i\}|
    \\mathrm\{i\}|
    \\imath\b|
    \\det|
    \\operatorname\{tr\}|
    \\operatorname\{rank\}|
    \\text\{rank\}|
    \\arg\{|
    \\Re\{|
    \\Im\{|
    \\operatorname\{Re\}|
    \\operatorname\{Im\}|
    \\text\{Re\}|
    \\text\{Im\}
    """,
    re.VERBOSE,
)


def should_treat_as_complex(latex_str: str) -> bool:
    return bool(complex_number_pattern.search(latex_str))


def verify(
    gold: list[Basic | MatrixBase | str] | Basic | MatrixBase | str,
    target: list[Basic | MatrixBase | str] | Basic | MatrixBase | str,
    float_rounding: int = 6,
    numeric_precision: int = 15,
    strict: bool = True,
    allow_set_relation_comp: bool = False,
    timeout_seconds: int | None = 5,
    raise_on_error: bool = False,
) -> bool:
    global TIMEOUT_WARNING_SHOWN
    if not TIMEOUT_WARNING_SHOWN and (timeout_seconds is None or timeout_seconds <= 0):
        logger.warning(
            "Timeout is disabled. Provide your own interruption logic if needed."
        )
        TIMEOUT_WARNING_SHOWN = True

    @timeout(timeout_seconds=timeout_seconds)
    def compare_single(
        gold_item: Basic | MatrixBase | str, target_item: Basic | MatrixBase | str
    ) -> bool:
        if isinstance(gold_item, (Basic, MatrixBase)) and isinstance(
            target_item, (Basic, MatrixBase)
        ):
            return sympy_expr_eq(
                gold_item,
                target_item,
                float_rounding,
                numeric_precision,
                allow_set_relation_comp,
                strict,
            )
        if isinstance(gold_item, str) and isinstance(target_item, str):
            gold_item = gold_item.strip()
            target_item = target_item.strip()
            return bool(gold_item and target_item and gold_item == target_item)
        return False

    def compare_single_wrapper(g, t):
        try:
            return compare_single(g, t)
        except ValueError as exc:
            if str(exc) == "signal only works in main thread of the main interpreter":
                raise ValueError(
                    "Math-Verify does not support signal-based timeouts in threaded "
                    "contexts. Set timeout_seconds=None and manage interruption "
                    "externally if you need threaded execution."
                ) from exc
            if raise_on_error:
                raise
            logger.debug("Error during comparison", exc_info=True)
            return False
        except Exception:
            if raise_on_error:
                raise
            logger.debug("Error during comparison", exc_info=True)
            return False
        except TimeoutException:
            if raise_on_error:
                raise
            logger.warning("Timeout during comparison")
            return False

    if not isinstance(gold, list):
        gold = [gold]
    if not isinstance(target, list):
        target = [target]
    return any(compare_single_wrapper(g, t) for g, t in product(gold, target))

