from math_verify import (
    ExprExtractionConfig,
    LatexExtractionConfig,
    StringExtractionConfig,
    parse,
    verify,
)


def compare_strings(
    gold: str,
    pred: str,
    match_types: list[str] | None = None,
    precision: int = 6,
    strict: bool = True,
    allow_set_relation_comp: bool = False,
):
    match_types = match_types or ["latex", "expr"]
    extraction_targets = []
    for match_type in match_types:
        if match_type == "latex":
            extraction_targets.append(LatexExtractionConfig(boxed_match_priority=0))
        elif match_type == "expr":
            extraction_targets.append(ExprExtractionConfig())
        elif match_type == "string":
            extraction_targets.append(StringExtractionConfig())

    gold_parsed = parse(gold, extraction_targets)
    pred_parsed = parse(pred, extraction_targets)
    return verify(
        gold_parsed,
        pred_parsed,
        float_rounding=precision,
        strict=strict,
        allow_set_relation_comp=allow_set_relation_comp,
    )


def test_fraction_and_decimal():
    assert compare_strings(r"$\frac{1}{2}$", "0.5")


def test_thousands_and_currency():
    assert compare_strings("7425000", "7,425,000", match_types=["expr"])
    assert compare_strings("1000.99", "$1,000.99", match_types=["expr"])


def test_percentages():
    assert compare_strings(r"$28\%$", "28 percent")
    assert compare_strings(r"$28\%$", r"$\boxed{28 pct}$")


def test_sets_and_unions():
    assert compare_strings(r"${1,3}\cup{2,4}$", r"${1,2,3,4}$")


def test_intervals_and_reversed_interval():
    assert compare_strings(r"$[0,1)$", r"$[0,1)$")
    assert compare_strings(r"$[0,1]$", r"$[1,0]$")


def test_relations_and_intervals():
    assert compare_strings(r"$$-793 < a < 10$$", r"$$(-793, 10)$$")
    assert compare_strings(r"$34x+45y-20z+100=0$", r"$-34x-45y+20z-100=0$")


def test_matrices():
    assert compare_strings(
        r"$\begin{pmatrix}1 & 0 \\ 0 & 1\end{pmatrix}$",
        r"$\begin{pmatrix}1 & 0 \\ 0 & 1\end{pmatrix}$",
    )


def test_strings():
    assert parse("The answer is A.", [StringExtractionConfig(lowercase=False)]) == ["A", "A"]
    assert parse("The answer is A.", [StringExtractionConfig(lowercase=True)]) == ["a", "A"]
    assert parse("Because B is valid", [StringExtractionConfig()]) == ["b", "B"]


def test_strict_variable_mode():
    assert not compare_strings(r"$f(x)$", r"$f(y)$", strict=True)
    assert compare_strings(r"$f(x)$", r"$f(y)$", strict=False)


def test_timeout_off_path():
    assert parse("1+1", parsing_timeout=None)
